import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"title":"Glossary"},"headers":[],"relativePath":"glossary/index.md","filePath":"glossary/index.md"}'),i={name:"glossary/index.md"};function o(l,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>All Fault keywords, operators, builtins, and types — alphabetical order.</p><p>One-liners cover items whose meaning is self-evident from the name. Entries with non-obvious behavior include a short example.</p><hr><h2 id="" tabindex="-1"><code>!</code> <a class="header-anchor" href="#" aria-label="Permalink to &quot;`!`&quot;">​</a></h2><p>Logical NOT. Negates a boolean expression in assertions, assumptions, and state conditions.</p><hr><h2 id="-1" tabindex="-1"><code>&amp;&amp;</code> <a class="header-anchor" href="#-1" aria-label="Permalink to &quot;`&amp;&amp;`&quot;">​</a></h2><p>Logical AND. Combines boolean expressions in assertions and assumptions.</p><hr><h2 id="-2" tabindex="-1"><code>&lt;-</code> <a class="header-anchor" href="#-2" aria-label="Permalink to &quot;`&lt;-`&quot;">​</a></h2><p>Increment operator. Adds the right-hand value to a stock field. Only valid inside flow functions.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p.instances &lt;- 1;   // p.instances = p.instances + 1</span></span></code></pre></div><hr><h2 id="-3" tabindex="-1"><code>-&gt;</code> <a class="header-anchor" href="#-3" aria-label="Permalink to &quot;`-&gt;`&quot;">​</a></h2><p>Decrement operator. Subtracts the right-hand value from a stock field. Only valid inside flow functions.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p.instances -&gt; 1;   // p.instances = p.instances - 1</span></span></code></pre></div><hr><h2 id="in-flow-functions" tabindex="-1"><code>=</code> (in flow functions) <a class="header-anchor" href="#in-flow-functions" aria-label="Permalink to &quot;`=` (in flow functions)&quot;">​</a></h2><p>Overwrite operator. Resets a stock field to the given value, discarding the previous value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s.active = true;    // overwrite, not increment</span></span></code></pre></div><p>Not to be confused with <code>==</code> (equality comparison) used in assertions.</p><hr><h2 id="-4" tabindex="-1"><code>||</code> <a class="header-anchor" href="#-4" aria-label="Permalink to &quot;`||`&quot;">​</a></h2><p>Logical OR. In state functions, signals a non-deterministic choice — the solver picks whichever branch satisfies the constraints. In assertions and assumptions, standard boolean OR.</p><p>See also: <a href="#choose"><code>choose</code></a>.</p><hr><h2 id="characteristic-access" tabindex="-1"><code>::</code> (characteristic access) <a class="header-anchor" href="#characteristic-access" aria-label="Permalink to &quot;`::` (characteristic access)&quot;">​</a></h2><p>Accesses an aggregate property of a <a href="#multiple"><code>multiple</code></a> flow set. Currently only <code>count</code> is supported.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init { l = multiple faucet; } {</span></span>\n<span class="line"><span>    l.in;</span></span>\n<span class="line"><span>};</span></span>\n<span class="line"><span>assume l::count &lt; 5;</span></span></code></pre></div><p><code>l::count</code> is the number of flow instances the solver created for <code>l</code>.</p><hr><h2 id="synthesis-slot" tabindex="-1"><code>__</code> (synthesis slot) <a class="header-anchor" href="#synthesis-slot" aria-label="Permalink to &quot;`__` (synthesis slot) {#synthesis-slot}&quot;">​</a></h2><p>A placeholder in the run block for program synthesis. The solver picks which flow function to call at this step. Each slot is resolved independently.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init { inst = new ops; } {</span></span>\n<span class="line"><span>    __;</span></span>\n<span class="line"><span>    __;</span></span>\n<span class="line"><span>    inst.deposit;   // explicit step can be mixed in</span></span>\n<span class="line"><span>    __;</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Use <code>assume</code> (not <code>assert</code>) to express the synthesis goal. See <a href="./../model-types/program-synthesis.html">Program Synthesis</a>.</p><hr><h2 id="advance" tabindex="-1"><code>advance()</code> <a class="header-anchor" href="#advance" aria-label="Permalink to &quot;`advance()`&quot;">​</a></h2><p>Transitions a component to the named state. Can target the current component (<code>this</code>) or another component by name.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>advance(this.idle)          // transition self to idle</span></span>\n<span class="line"><span>advance(replica.promoting)  // transition another component</span></span></code></pre></div><p><code>advance()</code> is only valid inside state functions in a <code>.fsystem</code> file.</p><hr><h2 id="always" tabindex="-1"><code>always</code> <a class="header-anchor" href="#always" aria-label="Permalink to &quot;`always`&quot;">​</a></h2><p>Temporal qualifier. The assertion must hold at every step of the model.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert buffer.size &gt;= 0 always;</span></span></code></pre></div><hr><h2 id="assert" tabindex="-1"><code>assert</code> <a class="header-anchor" href="#assert" aria-label="Permalink to &quot;`assert`&quot;">​</a></h2><p>Declares an invariant Fault should try to <em>violate</em>. The solver looks for a counterexample — a scenario where the expression is false. If it finds one, that trace is the result.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert pool.instances &gt; 0;</span></span>\n<span class="line"><span>assert queue.size &lt; queue.capacity always;</span></span></code></pre></div><p>See <a href="./../invariants/assertions.html">Assertions</a>.</p><hr><h2 id="assume" tabindex="-1"><code>assume</code> <a class="header-anchor" href="#assume" aria-label="Permalink to &quot;`assume`&quot;">​</a></h2><p>Restricts the solver to scenarios where the expression is true. In synthesis mode, <code>assume</code> expresses the goal the solver must satisfy.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume resources.blocks &gt;= 0;          // axiom: solver only explores valid states</span></span>\n<span class="line"><span>assume wallet.balance &gt; 100 eventually; // synthesis goal: find ops that reach this</span></span></code></pre></div><p>See <a href="./../invariants/assumptions.html">Assumptions</a>.</p><hr><h2 id="available" tabindex="-1"><code>available</code> <a class="header-anchor" href="#available" aria-label="Permalink to &quot;`available`&quot;">​</a></h2><p>Temporal qualifier for <code>unfunc</code>. Asserts that a function&#39;s <code>requires</code> precondition is satisfiable from the initial state.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume process available;</span></span></code></pre></div><p>Use this to guarantee the solver can actually select the function, not just that it is defined. See <a href="#unfunc"><code>unfunc</code></a>.</p><hr><h2 id="bool" tabindex="-1"><code>bool()</code> <a class="header-anchor" href="#bool" aria-label="Permalink to &quot;`bool()`&quot;">​</a></h2><p>Declares a stock field as an explicit boolean solvable — the solver picks <code>true</code> or <code>false</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def s = stock{</span></span>\n<span class="line"><span>    flag: bool(),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="choose" tabindex="-1"><code>choose</code> <a class="header-anchor" href="#choose" aria-label="Permalink to &quot;`choose`&quot;">​</a></h2><p>Makes a non-deterministic exclusive-or choice explicit. <code>choose A || B || C</code> ensures exactly one branch is taken — the solver cannot take multiple branches simultaneously.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idle: sfunc{</span></span>\n<span class="line"><span>    choose advance(this.active) || advance(this.expired);</span></span>\n<span class="line"><span>},</span></span></code></pre></div><p><code>choose</code> is optional — <code>||</code> already implies non-deterministic choice — but makes intent clear. Not valid inside <code>assert</code> or <code>assume</code>. See <a href="./../language-reference/special_syntax.html">Special Syntax</a>.</p><hr><h2 id="component" tabindex="-1"><code>component</code> <a class="header-anchor" href="#component" aria-label="Permalink to &quot;`component`&quot;">​</a></h2><p>Declares a state machine with named states.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>component breaker = states{</span></span>\n<span class="line"><span>    closed: sfunc{ ... },</span></span>\n<span class="line"><span>    open:   sfunc{ ... },</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Only valid in <code>.fsystem</code> files. See <a href="./../language-reference/components.html">Components</a>.</p><hr><h2 id="const" tabindex="-1"><code>const</code> <a class="header-anchor" href="#const" aria-label="Permalink to &quot;`const`&quot;">​</a></h2><p>Declares a constant value. If no value is given, the constant is an unknown — the solver picks its value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const maxRetries = 5;</span></span>\n<span class="line"><span>const threshold;          // unknown — solver picks</span></span>\n<span class="line"><span>const (</span></span>\n<span class="line"><span>    x = 10</span></span>\n<span class="line"><span>    y                     // unknown</span></span>\n<span class="line"><span>);</span></span></code></pre></div><hr><h2 id="def" tabindex="-1"><code>def</code> <a class="header-anchor" href="#def" aria-label="Permalink to &quot;`def`&quot;">​</a></h2><p>Defines a named stock or flow.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def pool = stock{ ... };</span></span>\n<span class="line"><span>def control = flow{ ... };</span></span></code></pre></div><hr><h2 id="emits" tabindex="-1"><code>emits</code> <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;`emits`&quot;">​</a></h2><p>Clause inside an <a href="#unfunc"><code>unfunc</code></a> that declares an effect on a stock field. Supports <code>=</code>, <code>&lt;-</code>, and <code>-&gt;</code> assignment forms.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>process: unfunc{</span></span>\n<span class="line"><span>    requires st.active,</span></span>\n<span class="line"><span>    emits st.processed = true,</span></span>\n<span class="line"><span>    emits st.count &lt;- 1,</span></span>\n<span class="line"><span>},</span></span></code></pre></div><hr><h2 id="eventually" tabindex="-1"><code>eventually</code> <a class="header-anchor" href="#eventually" aria-label="Permalink to &quot;`eventually`&quot;">​</a></h2><p>Temporal qualifier. The assertion must hold in at least one step.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert replica.active eventually;</span></span></code></pre></div><hr><h2 id="eventually-always" tabindex="-1"><code>eventually-always</code> <a class="header-anchor" href="#eventually-always" aria-label="Permalink to &quot;`eventually-always`&quot;">​</a></h2><p>Temporal qualifier. The assertion must eventually become true and then stay true for the remainder of the model.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert pool.instances &gt; 0 eventually-always;</span></span></code></pre></div><hr><h2 id="exclude" tabindex="-1"><code>exclude</code> <a class="header-anchor" href="#exclude" aria-label="Permalink to &quot;`exclude`&quot;">​</a></h2><p>Removes an inherited field when using <a href="#extends"><code>extends</code></a> in a stock definition.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def derived = stock{</span></span>\n<span class="line"><span>    extends base,</span></span>\n<span class="line"><span>    exclude limit,</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="extends" tabindex="-1"><code>extends</code> <a class="header-anchor" href="#extends" aria-label="Permalink to &quot;`extends`&quot;">​</a></h2><p>Inherits all fields from another stock definition.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def extended = stock{</span></span>\n<span class="line"><span>    extends base,</span></span>\n<span class="line"><span>    extra: 5,</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>To inherit from an imported spec, qualify the name with the import alias: <code>extends myimport.stockname</code>. See <a href="./../language-reference/stocks.html">Stocks</a>.</p><hr><h2 id="false" tabindex="-1"><code>false</code> <a class="header-anchor" href="#false" aria-label="Permalink to &quot;`false`&quot;">​</a></h2><p>Boolean literal.</p><hr><h2 id="float" tabindex="-1"><code>float()</code> <a class="header-anchor" href="#float" aria-label="Permalink to &quot;`float()`&quot;">​</a></h2><p>Constrains a stock field to the float domain. The solver picks any floating-point value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def s = stock{</span></span>\n<span class="line"><span>    reading: float(),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="flow" tabindex="-1"><code>flow</code> <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;`flow`&quot;">​</a></h2><p>Defines a set of functions that change stocks. Flows are instantiated with <code>new</code> in the run block or in a <code>.fsystem</code> global.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def ops = flow{</span></span>\n<span class="line"><span>    st: new myStock,</span></span>\n<span class="line"><span>    doThing: func{ ... },</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>See <a href="./../language-reference/flows.html">Flows</a>.</p><hr><h2 id="for-removed" tabindex="-1"><code>for</code> <em>(removed)</em> <a class="header-anchor" href="#for-removed" aria-label="Permalink to &quot;`for` *(removed)*&quot;">​</a></h2><p>Previously used to set the number of verification rounds (<code>for 2 run{}</code>). Removed in June 2026. Use a run block with the desired number of explicit steps instead.</p><hr><h2 id="func" tabindex="-1"><code>func</code> <a class="header-anchor" href="#func" aria-label="Permalink to &quot;`func`&quot;">​</a></h2><p>Declares an imperative function inside a <code>flow{}</code> definition. Flow functions contain arithmetic expressions and stock mutations (<code>&lt;-</code>, <code>-&gt;</code>, <code>=</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>refill: func{</span></span>\n<span class="line"><span>    b.tokens &lt;- 1;</span></span>\n<span class="line"><span>},</span></span></code></pre></div><p>For state bodies inside a <code>component</code>, use <a href="#sfunc"><code>sfunc</code></a> instead. See also: <a href="#unfunc"><code>unfunc</code></a> for the declarative alternative.</p><hr><h2 id="global" tabindex="-1"><code>global</code> <a class="header-anchor" href="#global" aria-label="Permalink to &quot;`global`&quot;">​</a></h2><p>Declares a globally-scoped flow instance in a <code>.fsystem</code> file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global record = new cache.record;</span></span></code></pre></div><hr><h2 id="import" tabindex="-1"><code>import</code> <a class="header-anchor" href="#import" aria-label="Permalink to &quot;`import`&quot;">​</a></h2><p>Imports a <code>.fspec</code> file into a <code>.fsystem</code> file. Only one level of imports is allowed — specs cannot import other specs.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import(&quot;cache.fspec&quot;);</span></span>\n<span class="line"><span>import(cache &quot;cache.fspec&quot;);   // aliased import</span></span></code></pre></div><hr><h2 id="int" tabindex="-1"><code>int()</code> <a class="header-anchor" href="#int" aria-label="Permalink to &quot;`int()`&quot;">​</a></h2><p>Constrains a stock field to the integer domain. The solver picks any integer value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def s = stock{</span></span>\n<span class="line"><span>    offset: int(),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="leave" tabindex="-1"><code>leave()</code> <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;`leave()`&quot;">​</a></h2><p>Exits the current state or a named state. The opposite of <code>advance()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leave();              // exit current state</span></span>\n<span class="line"><span>leave(this.active);   // exit the named state</span></span></code></pre></div><hr><h2 id="multiple" tabindex="-1"><code>multiple</code> <a class="header-anchor" href="#multiple" aria-label="Permalink to &quot;`multiple`&quot;">​</a></h2><p>Creates an unbounded set of flow instances. The solver decides how many instances to use.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init { l = multiple faucet; } {</span></span>\n<span class="line"><span>    l.in;</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Only valid for flows. Use <a href="#-characteristic-access"><code>::count</code></a> to constrain how many instances the solver may create.</p><hr><h2 id="natural-n" tabindex="-1"><code>natural(n)</code> <a class="header-anchor" href="#natural-n" aria-label="Permalink to &quot;`natural(n)`&quot;">​</a></h2><p>Constrains a stock field to a natural number starting from <code>n</code> — a non-negative integer.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def q = stock{</span></span>\n<span class="line"><span>    size: natural(0),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="new" tabindex="-1"><code>new</code> <a class="header-anchor" href="#new" aria-label="Permalink to &quot;`new`&quot;">​</a></h2><p>Instantiates a stock or flow.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cluster = new control;     // instantiate a flow</span></span>\n<span class="line"><span>p: new pool,               // initialize a stock inside a flow</span></span></code></pre></div><hr><h2 id="nft-n" tabindex="-1"><code>nft N</code> <a class="header-anchor" href="#nft-n" aria-label="Permalink to &quot;`nft N`&quot;">​</a></h2><p>Temporal qualifier. The assertion must hold no fewer than <code>N</code> times across all rounds.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert checkpoint.reached nft 2;</span></span></code></pre></div><hr><h2 id="nmt-n" tabindex="-1"><code>nmt N</code> <a class="header-anchor" href="#nmt-n" aria-label="Permalink to &quot;`nmt N`&quot;">​</a></h2><p>Temporal qualifier. The assertion must hold no more than <code>N</code> times across all rounds.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert error.triggered nmt 1;</span></span></code></pre></div><hr><h2 id="now" tabindex="-1"><code>now</code> <a class="header-anchor" href="#now" aria-label="Permalink to &quot;`now`&quot;">​</a></h2><p>The current round index. Used to reference a stock&#39;s value at a previous round.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p.value &lt;- p.value[now-1];   // add previous round&#39;s value</span></span>\n<span class="line"><span>b.a &lt;- b.a[0] - 2;           // reference initial value</span></span></code></pre></div><hr><h2 id="param" tabindex="-1"><code>param()</code> <a class="header-anchor" href="#param" aria-label="Permalink to &quot;`param()`&quot;">​</a></h2><p>Marks a stock field as a template parameter for use with <code>-m template</code> mode and <code>fault render</code>. The compiler generates a <code>.params.json</code> file; <code>fault render</code> substitutes concrete values at model-check time.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def limits = stock{</span></span>\n<span class="line"><span>    threshold: param(),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>See <a href="./../data-types/">Data Types</a>.</p><hr><h2 id="requires" tabindex="-1"><code>requires</code> <a class="header-anchor" href="#requires" aria-label="Permalink to &quot;`requires`&quot;">​</a></h2><p>Clause inside an <a href="#unfunc"><code>unfunc</code></a> that declares a precondition. The solver will only select this function when the precondition holds.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>process: unfunc{</span></span>\n<span class="line"><span>    requires queue.pending &gt; 0,</span></span>\n<span class="line"><span>    emits queue.pending -&gt; 1,</span></span>\n<span class="line"><span>},</span></span></code></pre></div><hr><h2 id="run" tabindex="-1"><code>run</code> <a class="header-anchor" href="#run" aria-label="Permalink to &quot;`run`&quot;">​</a></h2><p>Declares the execution block. The <code>init</code> section instantiates flows and sets up initial conditions; the body lists the steps to verify.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init {</span></span>\n<span class="line"><span>    inst = new myFlow;</span></span>\n<span class="line"><span>    inst.stock = otherStock;   // optional swap</span></span>\n<span class="line"><span>} {</span></span>\n<span class="line"><span>    inst.funcA;</span></span>\n<span class="line"><span>    inst.funcB | inst.funcC;   // concurrent</span></span>\n<span class="line"><span>    __;                        // synthesis slot</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Each line in the body is one round. The number of rounds determines verification depth.</p><hr><h2 id="sfunc" tabindex="-1"><code>sfunc</code> <a class="header-anchor" href="#sfunc" aria-label="Permalink to &quot;`sfunc` {#sfunc}&quot;">​</a></h2><p>Declares a state body inside a <code>component</code>. State functions may contain <code>advance()</code>, <code>stay()</code>, <code>leave()</code>, flow triggers, and stock conditionals. They may <strong>not</strong> contain stock mutations (<code>&lt;-</code>, <code>-&gt;</code>, <code>=</code>).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>component breaker = states{</span></span>\n<span class="line"><span>    closed: sfunc{</span></span>\n<span class="line"><span>        advance(this.open) || stay();</span></span>\n<span class="line"><span>    },</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Replaces the old <code>func</code> keyword for state bodies (breaking change, 2026-08-17). Flow functions still use <a href="#func"><code>func</code></a>.</p><hr><h2 id="spec" tabindex="-1"><code>spec</code> <a class="header-anchor" href="#spec" aria-label="Permalink to &quot;`spec`&quot;">​</a></h2><p>Declares the name of a <code>.fspec</code> file. Must be the first statement.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec cache;</span></span></code></pre></div><hr><h2 id="start-removed" tabindex="-1"><code>start</code> <em>(removed)</em> <a class="header-anchor" href="#start-removed" aria-label="Permalink to &quot;`start` *(removed)*&quot;">​</a></h2><p>Previously used to declare the initial state of each component in a <code>.fsystem</code> file. Removed in June 2026. Use a <code>run</code> block instead.</p><hr><h2 id="stay" tabindex="-1"><code>stay()</code> <a class="header-anchor" href="#stay" aria-label="Permalink to &quot;`stay()`&quot;">​</a></h2><p>Remains in the current state. A no-op that makes intent explicit.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idle: sfunc{</span></span>\n<span class="line"><span>    stay();</span></span>\n<span class="line"><span>},</span></span></code></pre></div><p>Omitting <code>stay()</code> when no other transition is possible is equivalent but less readable.</p><hr><h2 id="states" tabindex="-1"><code>states</code> <a class="header-anchor" href="#states" aria-label="Permalink to &quot;`states`&quot;">​</a></h2><p>Declares the body of a <a href="#component"><code>component</code></a> as a map of named state functions.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>component breaker = states{</span></span>\n<span class="line"><span>    closed: sfunc{ ... },</span></span>\n<span class="line"><span>    open:   sfunc{ ... },</span></span>\n<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="stock" tabindex="-1"><code>stock</code> <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;`stock`&quot;">​</a></h2><p>Defines a named reservoir of values — the state the model tracks over time.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def pool = stock{</span></span>\n<span class="line"><span>    instances: 0,</span></span>\n<span class="line"><span>    loading: 0,</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>See <a href="./../language-reference/stocks.html">Stocks</a>.</p><hr><h2 id="system" tabindex="-1"><code>system</code> <a class="header-anchor" href="#system" aria-label="Permalink to &quot;`system`&quot;">​</a></h2><p>Declares the name of a <code>.fsystem</code> file. Must be the first statement.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>system dbCluster;</span></span></code></pre></div><hr><h2 id="this" tabindex="-1"><code>this</code> <a class="header-anchor" href="#this" aria-label="Permalink to &quot;`this`&quot;">​</a></h2><p>Self-reference inside a component state function. Used to target the current component in <code>advance()</code> and <code>leave()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>advance(this.idle);</span></span>\n<span class="line"><span>leave(this.active);</span></span></code></pre></div><hr><h2 id="true" tabindex="-1"><code>true</code> <a class="header-anchor" href="#true" aria-label="Permalink to &quot;`true`&quot;">​</a></h2><p>Boolean literal.</p><hr><h2 id="uncertain-mean-sigma" tabindex="-1"><code>uncertain(mean, sigma)</code> <a class="header-anchor" href="#uncertain-mean-sigma" aria-label="Permalink to &quot;`uncertain(mean, sigma)`&quot;">​</a></h2><p>Declares a stock field as a normally-distributed uncertain value. The solver assigns values drawn from the distribution and annotates results with probabilities.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def sensor = stock{</span></span>\n<span class="line"><span>    reading: uncertain(1, 0.5),   // mean=1, sigma=0.5</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Results include probability annotations: <code>1.500000 (0.483941)</code>. See <a href="./../data-types/">Data Types</a>.</p><hr><h2 id="unfunc" tabindex="-1"><code>unfunc</code> <a class="header-anchor" href="#unfunc" aria-label="Permalink to &quot;`unfunc` {#unfunc}&quot;">​</a></h2><p>A declarative alternative to <code>func</code> that uses <code>requires</code>/<code>emits</code> clauses instead of imperative steps. Designed for use with program synthesis.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def ops = flow{</span></span>\n<span class="line"><span>    q: new queue,</span></span>\n<span class="line"><span>    process: unfunc{</span></span>\n<span class="line"><span>        requires q.pending &gt; 0,</span></span>\n<span class="line"><span>        emits q.pending -&gt; 1,</span></span>\n<span class="line"><span>        emits q.done &lt;- 1,</span></span>\n<span class="line"><span>    },</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>See <a href="./../language-reference/flows.html">Flows</a> and <a href="./../model-types/program-synthesis.html">Program Synthesis</a>.</p><hr><h2 id="unknown" tabindex="-1"><code>unknown()</code> <a class="header-anchor" href="#unknown" aria-label="Permalink to &quot;`unknown()`&quot;">​</a></h2><p>Declares a stock field or constant whose value the solver picks freely. Equivalent to declaring a field with no assigned value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def s = stock{</span></span>\n<span class="line"><span>    blocks: unknown(),</span></span>\n<span class="line"><span>    table,              // implicit unknown</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Use unknowns when you want the solver to find interesting starting conditions rather than testing from a fixed baseline. See <a href="./../data-types/">Data Types</a>.</p><hr><h2 id="when-then" tabindex="-1"><code>when / then</code> <a class="header-anchor" href="#when-then" aria-label="Permalink to &quot;`when / then`&quot;">​</a></h2><p>Conditional invariant form. <code>when A then B</code> asserts that B must be true whenever A is true.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert when state.accessGranted then state.authenticated;</span></span>\n<span class="line"><span>assume when queue.full then queue.size &gt;= queue.capacity always;</span></span></code></pre></div><p>Valid with both <code>assert</code> and <code>assume</code>. Accepts temporal qualifiers. See <a href="./../invariants/assertions.html">Assertions</a>.</p><hr><h2 id="whole" tabindex="-1"><code>whole()</code> <a class="header-anchor" href="#whole" aria-label="Permalink to &quot;`whole()`&quot;">​</a></h2><p>Constrains a stock field to a non-negative integer. The solver picks any whole number.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def t = stock{</span></span>\n<span class="line"><span>    ticks: whole(),</span></span>\n<span class="line"><span>};</span></span></code></pre></div><p>Similar to <code>natural(0)</code> but signals that the starting value is unconstrained.</p>',240)])])}const b=e(i,[["render",o]]);export{u as __pageData,b as default};
